69:     public <V, C extends Context> V executeSingleConnectionFunction(
70:         String componentName, int componentVersion, ComponentConnection componentConnection,
71:         C context, ErrorType errorType, BiFunction<ComponentConnection, C, V> performFunction,
72:         Function<ComponentConnection, C> contextFunction) {
73: 
74:         try {
75:             return performFunction.apply(componentConnection, context);
76:         } catch (Exception exception) {
77:             if (componentConnection == null ||
78:                 !AuthorizationUtils.isApplicable(componentConnection.authorizationName())) {
79: 
80:                 throw exception;
81:             }
82: 
83:             List<Object> refreshOn = connectionDefinitionService.getAuthorizationRefreshOn(
84:                 componentName, componentConnection.version(),
85:                 Objects.requireNonNull(componentConnection.authorizationName()));
86: 
87:             if (componentConnection.canCredentialsBeRefreshed() &&
88:                 RefreshCredentialsUtils.matches(refreshOn, exception)) {
89: 
90:                 componentConnection = getRefreshedCredentialsComponentConnection(componentConnection, context);
91: 
92:                 return performFunction.apply(componentConnection, contextFunction.apply(componentConnection));
93:             }
94: 
95:             if (exception instanceof ProviderException) {
96:                 throw new ConfigurationException(exception, errorType);
97:             }
98: 
99:             if (exception instanceof ConfigurationException ||
100:                 exception instanceof ExecutionException) {
101: 
102:                 throw exception;
103:             }
104: 
105:             throw exception;
106:         }
107:     }
108: 
109:     private ComponentConnection getRefreshedCredentialsComponentConnection(
110:         ComponentConnection componentConnection, Context context) {
111: 
112:         Connection connection;
113:         Map<String, ?> parameters;
114: 
115:         try {
116:             if (componentConnection.isAuthorizationOauth2AuthorizationCode()) {
117:                 Authorization.RefreshTokenResponse refreshTokenResponse =
118:                     connectionDefinitionService.executeRefresh(
119:                         componentConnection.componentName(), componentConnection.version(),
120:                         Objects.requireNonNull(componentConnection.authorizationName()),
121:                         componentConnection.getParameters(), context);
122: 
123:                 parameters = new HashMap<>() {
124:                     {
125:                         put(ACCESS_TOKEN, refreshTokenResponse.accessToken());
126: 
127:                         if (refreshTokenResponse.refreshToken() != null) {
128:                             put(REFRESH_TOKEN, refreshTokenResponse.refreshToken());
129:                         }
130: 
131:                         if (refreshTokenResponse.expiresIn() != null) {
132:                             put(EXPIRES_IN, refreshTokenResponse.expiresIn());
133:                         }
134:                     }
135:                 };
136:             } else {
137:                 parameters = connectionDefinitionService.executeAcquire(
138:                     componentConnection.componentName(), componentConnection.version(),
139:                     Objects.requireNonNull(componentConnection.authorizationName()),
140:                     componentConnection.getParameters(), context);
141:             }
142: 
143:             Cache cache = Objects.requireNonNull(cacheManager.getCache(CACHE));
144: 
145:             ReentrantLock reentrantLock = Validate.notNull(
146:                 cache.get(
147:                     TenantCacheKeyUtils.getKey(componentConnection.connectionId()), () -> new ReentrantLock(true)),
148:                 "reentrantLock");
149: 
150:             reentrantLock.lock();
151: 
152:             try {
153:                 connection = connectionService.updateConnectionParameters(
154:                     componentConnection.connectionId(), parameters);
155:             } finally {
156:                 reentrantLock.unlock();
157:             }
158:         } catch (Exception e) {
159:             connectionService.updateConnectionCredentialStatus(
160:                 componentConnection.connectionId(), Connection.CredentialStatus.INVALID);
161: 
162:             throw e;
163:         }
164: 
165:         return new ComponentConnection(
166:             componentConnection.componentName(), connection.getConnectionVersion(), componentConnection.connectionId(),
167:             connection.getParameters(), connection.getAuthorizationName());
168:     }
169: }
