306:     private static Property getProperty(
307:         String propertyName, List<? extends Property> properties, Parameters inputParameters,
308:         Parameters connectionParameters, Map<String, String> lookupDependsOnPaths, Context context) throws Exception {
309: 
310:         List<String> subProperties = Arrays.asList(propertyName.split("\\."));
311: 
312:         if (subProperties.size() == 1) {
313:             if (propertyName.endsWith("]")) {
314:                 ArrayProperty arrayProperty = (ArrayProperty) CollectionUtils.getFirst(
315:                     properties,
316:                     curProperty -> Objects.equals(
317:                         curProperty.getName(), propertyName.substring(0, propertyName.length() - 3)));
318: 
319:                 List<? extends Property> items = OptionalUtils.get(arrayProperty.getItems());
320: 
321:                 return items.getFirst();
322:             } else {
323:                 return CollectionUtils.getFirst(
324:                     properties, property -> Objects.equals(propertyName, property.getName()));
325:             }
326:         } else {
327:             String firstSubPropertyName = getFirstSubPropertyName(subProperties);
328: 
329:             Property firstProperty = CollectionUtils.getFirst(
330:                 properties, property -> Objects.equals(property.getName(), firstSubPropertyName));
331: 
332:             if (firstProperty instanceof Property.DynamicPropertiesProperty dynamicPropertiesProperty) {
333:                 PropertiesDataSource<?> dynamicPropertiesDataSource = dynamicPropertiesProperty
334:                     .getDynamicPropertiesDataSource();
335: 
336:                 PropertiesDataSource.PropertiesFunction propertiesFunction = dynamicPropertiesDataSource
337:                     .getProperties();
338: 
339:                 List<? extends Property.ValueProperty<?>> dynamicPropertyProperties;
340: 
341:                 if (propertiesFunction instanceof ActionPropertiesFunction actionPropertiesFunction) {
342:                     dynamicPropertyProperties = actionPropertiesFunction.apply(
343:                         inputParameters, connectionParameters, lookupDependsOnPaths, (ActionContext) context);
344:                 } else {
345:                     dynamicPropertyProperties = ((TriggerPropertiesFunction) propertiesFunction)
346:                         .apply(inputParameters, connectionParameters, lookupDependsOnPaths, (TriggerContext) context);
347:                 }
348: 
349:                 return getProperty(
350:                     String.join(".", subProperties.subList(1, subProperties.size())),
351:                     dynamicPropertyProperties, inputParameters, connectionParameters, lookupDependsOnPaths, context);
352:             } else if (firstProperty instanceof ArrayProperty arrayProperty) {
353:                 List<? extends Property.ValueProperty<?>> items = OptionalUtils.get(arrayProperty.getItems());
354: 
355:                 if (items.getFirst() instanceof ObjectProperty objectProperty) {
356:                     items = OptionalUtils.get(objectProperty.getProperties());
357:                 }
358: 
359:                 return getProperty(
360:                     String.join(".", subProperties.subList(1, subProperties.size())), items, inputParameters,
361:                     connectionParameters, lookupDependsOnPaths, context);
362:             } else {
363:                 ObjectProperty objectProperty = (ObjectProperty) CollectionUtils.getFirst(
364:                     properties, property -> Objects.equals(property.getName(), subProperties.getFirst()));
365: 
366:                 for (int i = 1; i < subProperties.size() - 1; i++) {
367:                     String subProperty = subProperties.get(i);
368: 
369:                     if (subProperty.endsWith("]")) {
370:                         ArrayProperty arrayProperty = (ArrayProperty) CollectionUtils.getFirst(
371:                             OptionalUtils.get(objectProperty.getProperties()),
372:                             curProperty -> Objects.equals(
373:                                 curProperty.getName(), subProperty.substring(0, subProperty.length() - 3)));
374: 
375:                         List<? extends Property> items = OptionalUtils.get(arrayProperty.getItems());
376: 
377:                         objectProperty = (ObjectProperty) items.getFirst();
378:                     } else {
379:                         objectProperty = (ObjectProperty) CollectionUtils.getFirst(
380:                             OptionalUtils.get(objectProperty.getProperties()),
381:                             curProperty -> Objects.equals(curProperty.getName(), subProperty));
382:                     }
383:                 }
384: 
385:                 return CollectionUtils.getFirst(
386:                     OptionalUtils.get(objectProperty.getProperties()),
387:                     curProperty -> Objects.equals(curProperty.getName(), subProperties.getLast()));
388:             }
389:         }
390:     }
391: 
392:     private static String getFirstSubPropertyName(List<String> subProperties) {
393:         String firstSubPropertyName = subProperties.getFirst();
394: 
395:         if (firstSubPropertyName.endsWith("]")) {
396:             firstSubPropertyName = firstSubPropertyName.substring(0, firstSubPropertyName.indexOf("["));
397:         }
398:         return firstSubPropertyName;
399:     }
