401:     private void validate(List<ComponentDefinition> componentDefinitions) {
402:         for (ComponentDefinition componentDefinition : componentDefinitions) {
403:             List<? extends ActionDefinition> actionDefinitions = OptionalUtils.orElse(
404:                 componentDefinition.getActions(), List.of());
405: 
406:             for (ActionDefinition actionDefinition : actionDefinitions) {
407:                 if (log.isTraceEnabled()) {
408:                     log.trace("Validating %s.%s".formatted(componentDefinition.getName(), actionDefinition.getName()));
409:                 }
410: 
411:                 PropertyUtils.checkInputProperties(
412:                     OptionalUtils.orElse(actionDefinition.getProperties(), List.of()));
413:                 PropertyUtils.checkOutputProperty(
414:                     OptionalUtils.mapOrElse(actionDefinition.getOutputDefinition(), OutputDefinition::getOutputSchema,
415:                         null));
416:             }
417: 
418:             List<? extends TriggerDefinition> triggerDefinitions = OptionalUtils.orElse(
419:                 componentDefinition.getTriggers(), List.of());
420: 
421:             for (TriggerDefinition triggerDefinition : triggerDefinitions) {
422:                 if (log.isTraceEnabled()) {
423:                     log.trace("Validating %s.%s".formatted(componentDefinition.getName(), triggerDefinition.getName()));
424:                 }
425: 
426:                 PropertyUtils.checkInputProperties(OptionalUtils.orElse(triggerDefinition.getProperties(), List.of()));
427:                 PropertyUtils.checkOutputProperty(
428:                     OptionalUtils.mapOrElse(triggerDefinition.getOutputDefinition(), OutputDefinition::getOutputSchema,
429:                         null));
