431:                 if (triggerDefinition.getType() == null) {
432:                     throw new IllegalArgumentException(
433:                         "Trigger type for trigger=%s is not defined".formatted(triggerDefinition.getName()));
434:                 }
435:             }
436:         }
437:     }
