53: /**
54:  * @author Nikolina Spehar
55:  */
56: public class CryptoHelperRsaDecryptAction {
57: 
58:     public static final ModifiableActionDefinition ACTION_DEFINITION = action("PGPdecrypt")
59:         .title("PGP Decrypt")
60:         .description("Decrypts PGP encrypted file using private key and passphrase.")
61:         .properties(
62:             string(PRIVATE_KEY)
63:                 .label("Private PGP Key")
64:                 .description(
65:                     "Private PGP key that will decrypt the file. Make sure there is a new line after the PGP header.")
66:                 .controlType(ControlType.TEXT_AREA)
67:                 .required(true),
68:             fileEntry(FILE)
69:                 .label("File")
70:                 .description("File that will be decrypted.")
71:                 .required(true),
72:             string(PASSPHRASE)
73:                 .label("Passphrase")
74:                 .description("Passphrase that was used for encryption.")
75:                 .required(true))
76:         .output(
77:             outputSchema(
78:                 fileEntry()
79:                     .description("Decrypted file.")))
80:         .perform(CryptoHelperPGPDecryptAction::perform);
81: 
82:     private CryptoHelperPGPDecryptAction() {
83:     }
84: 
85:     public static FileEntry perform(Parameters inputParameters, Parameters connectionParameters, Context context)
86:         throws Exception {
87: 
88:         Security.addProvider(new BouncyCastleProvider());
89: 
90:         FileEntry encryptedFileEntry = inputParameters.getRequiredFileEntry(FILE);
91:         byte[] encryptedBytes = context.file(file -> file.readAllBytes(encryptedFileEntry));
92: 
93:         ByteArrayInputStream encryptedInputStream = new ByteArrayInputStream(encryptedBytes);
94: 
95:         PGPObjectFactory pgpObjectFactory = new PGPObjectFactory(
96:             PGPUtil.getDecoderStream(encryptedInputStream), new JcaKeyFingerprintCalculator());
97:         PGPEncryptedDataList pgpEncryptedDataList = (PGPEncryptedDataList) pgpObjectFactory.nextObject();
98: 
99:         PGPPublicKeyEncryptedData pgpPublicKeyEncryptedData = (PGPPublicKeyEncryptedData) pgpEncryptedDataList.get(0);
100: 
101:         PGPPrivateKey pgpPrivateKey = getPrivateKey(
102:             inputParameters.getRequiredString(PRIVATE_KEY), inputParameters.getRequiredString(PASSPHRASE),
103:             pgpEncryptedDataList);
104: 
105:         InputStream decryptedDataStream =
106:             pgpPublicKeyEncryptedData.getDataStream(
107:                 new JcePublicKeyDataDecryptorFactoryBuilder()
108:                     .setProvider(BouncyCastleProvider.PROVIDER_NAME)
109:                     .build(pgpPrivateKey));
110: 
111:         ByteArrayOutputStream decryptedOutputStream = getDecryptedDataFromStream(decryptedDataStream);
112: 
113:         return context.file(
114:             file -> file.storeContent("decrypted.", new ByteArrayInputStream(decryptedOutputStream.toByteArray())));
115:     }
116: 
117:     private static PGPPrivateKey getPrivateKey(
118:         String privateKeyString, String passphrase, PGPEncryptedDataList encDataList)
119:         throws IOException, PGPException {
120: 
121:         InputStream privateKeyInputStream = new ByteArrayInputStream(privateKeyString.getBytes(StandardCharsets.UTF_8));
122: 
123:         PGPSecretKeyRingCollection pgpSecretKeyRingCollection = new PGPSecretKeyRingCollection(
124:             PGPUtil.getDecoderStream(privateKeyInputStream), new JcaKeyFingerprintCalculator());
125: 
126:         PGPPrivateKey privateKey = null;
127: 
128:         Iterator<PGPEncryptedData> iterator = encDataList.getEncryptedDataObjects();
129: 
130:         while (privateKey == null && iterator.hasNext()) {
131:             PGPPublicKeyEncryptedData pgpPublicKeyEncryptedData = (PGPPublicKeyEncryptedData) iterator.next();
132:             PGPSecretKey pgpSecKey = pgpSecretKeyRingCollection.getSecretKey(pgpPublicKeyEncryptedData.getKeyID());
133: 
134:             privateKey = pgpSecKey == null ? null : pgpSecKey.extractPrivateKey(
135:                 new JcePBESecretKeyDecryptorBuilder()
136:                     .setProvider(BouncyCastleProvider.PROVIDER_NAME)
137:                     .build(passphrase.toCharArray()));
138:         }
139: 
140:         return privateKey;
141:     }
142: 
143:     private static ByteArrayOutputStream getDecryptedDataFromStream(InputStream decryptedDataStream)
144:         throws IOException {
145:         ByteArrayOutputStream decryptedData = new ByteArrayOutputStream();
146: 
147:         int ch;
148: 
149:         while ((ch = decryptedDataStream.read()) >= 0) {
150:             decryptedData.write(ch);
151:         }
152: 
153:         return decryptedData;
154:     }
155: }
